{"cards": [{"node_code": "N_d3b72eda06d215a3", "definition": "研究神经肌肉接头、周围神经及骨骼肌结构功能异常导致的疾病，涵盖肌病、神经肌肉接头病及周围神经病。", "boundary": "聚焦于运动单位（神经、接头、肌肉）的病变。与“周围神经疾病”节点存在交叉，本节点侧重肌肉及接头层面的病理生理与诊断（如肌电图、肌肉活检）；与“神经退行性疾病”区分，本节点主要指非进行性中枢神经元丢失的肌肉或周围神经病变。", "includes": ["肌营养不良、炎性肌病及代谢性肌病", "重症肌无力、先天性肌无力综合征等神经肌肉接头疾病", "肌病相关的电生理诊断与肌肉病理分析"], "excludes": ["以中枢神经系统（脑、脊髓）病变为主的运动障碍（主挂运动障碍疾病或脊髓疾病）", "单纯的感觉神经病变（主挂周围神经疾病）"], "sibling_distinctions": [{"other_code": "N_7697f4fdd43d2cd5", "rule": "周围神经疾病侧重神经干、神经根及神经丛的病变；本节点侧重肌肉本身及神经肌肉接头的病变，常需结合肌电图鉴别。"}, {"other_code": "N_f75f7d8c87ba339f", "rule": "神经退行性疾病侧重中枢神经元（如运动神经元、皮层神经元）的进行性丢失；本节点侧重外周运动单位（肌肉、接头、周围神经）的病变。"}], "cross_boundary_rule": "若疾病同时累及中枢运动神经元和周围神经/肌肉（如肌萎缩侧索硬化），主挂神经退行性疾病或运动障碍疾病，本节点作为次关联收录其外周表现。"}, {"node_code": "N_f75f7d8c87ba339f", "definition": "研究中枢神经系统神经元进行性丢失、变性及其导致的认知、运动或感觉功能衰退的疾病。", "boundary": "涵盖阿尔茨海默病、帕金森病、肌萎缩侧索硬化（ALS）、多系统萎缩等。与“运动障碍疾病”区分，本节点侧重神经元的退行性病理机制及不可逆损伤；与“神经肌肉疾病”区分，本节点侧重中枢或运动神经元层面的病变，而非肌肉或接头本身。", "includes": ["阿尔茨海默病、路易体痴呆等神经认知障碍", "帕金森病、多系统萎缩等锥体外系退行性变", "肌萎缩侧索硬化（ALS）等运动神经元病"], "excludes": ["由急性血管事件（卒中）或感染引起的继发性神经损伤（主挂脑血管病或感染节点）", "以精神症状为主且无明确器质性退行性变的疾病（主挂精神病学）"], "sibling_distinctions": [{"other_code": "N_34498f6c54a2de62", "rule": "运动障碍疾病侧重运动控制异常的症状学分类（如震颤、肌张力障碍）；本节点侧重导致这些症状的神经元退行性病理机制及疾病实体。"}, {"other_code": "N_d3b72eda06d215a3", "rule": "神经肌肉疾病侧重外周运动单位（肌肉、接头）；本节点侧重中枢或运动神经元本身的退行性病变。"}], "cross_boundary_rule": "若退行性疾病主要表现为特定运动障碍症状，可关联运动障碍疾病；若累及外周神经肌肉接头，可关联神经肌肉疾病，但疾病实体主挂本节点。"}, {"node_code": "N_dd2f791373e5c80a", "definition": "研究由遗传因素或胚胎发育异常导致的神经系统结构、功能缺陷及相关疾病。", "boundary": "涵盖遗传性共济失调、先天性肌病、神经管缺陷、脑发育畸形及遗传性代谢性脑病。与“神经退行性疾病”区分，本节点侧重先天或早期发育起源及遗传机制；与“神经肌肉疾病”区分，本节点侧重发育过程异常或遗传背景，而非单纯的肌肉病变。", "includes": ["遗传性共济失调、遗传性痉挛性截瘫", "先天性肌病、神经管缺陷及脑发育畸形", "遗传性代谢性脑病及染色体异常导致的神经发育障碍"], "excludes": ["后天获得的神经系统损伤（如外伤、卒中）（主挂相应损伤节点）", "非遗传性的获得性神经退行性疾病（主挂神经退行性疾病）"], "sibling_distinctions": [{"other_code": "N_f75f7d8c87ba339f", "rule": "神经退行性疾病侧重成年后发生的进行性神经元丢失；本节点侧重遗传背景或发育起源的神经系统疾病，部分可表现为退行性过程但起源不同。"}, {"other_code": "N_d3b72eda06d215a3", "rule": "神经肌肉疾病侧重肌肉及接头的病理生理；本节点侧重遗传或发育异常导致的神经系统整体或局部缺陷，包括先天性肌病。"}], "cross_boundary_rule": "若遗传性疾病主要累及肌肉，可关联神经肌肉疾病；若表现为进行性退行性变，可关联神经退行性疾病，但遗传机制与发育起源主挂本节点。"}]}
